        public async Task<TEntity> NotifyThreadBySmsInternalAsync<TEntity>(IEnumerable<TEntity> entities, object message, object recipients_data, object msg_vals, object sms_content, object sms_numbers, object sms_pid_to_number, object resend_existing, object put_in_queue) where TEntity : IEntity<Guid>, IMailThreadable
